    };

    // 注入轨迹:命令行 `--trace [路径]` 优先,其次环境变量 `SCRCPY_PAD_TRACE`,
    // **两者都没有时也落盘到配置目录**(双击启动不会继承环境变量,用户 2026-10-11
    // 因此整局没留下现场;总量限制见 trace::prune_old_traces)。
    // 放在 diag 之后、任何输入设备枚举之前 —— 第一条按键事件也要能被记下。
    trace::init_from_args(&std::env::args().collect::<Vec<_>>());

    if std::env::args().any(|a| a == "--selftest") {
        diag::snapshot_environment();
        let code = selftest();
        finish(code);
    }

    // 蒙版窗口自检(批次 0):透明 / 置顶 / 绘制 / 点击归属 / 不抢焦点 / 无残窗。
    // 与 `--selftest` 分开:那个要连真机,这个纯本机窗口层,几秒钟就能跑完。
    if std::env::args().any(|a| a == "--mask-selftest") {
        diag::snapshot_environment();
        let code = mask::selftest();
        finish(code);
    }

    diag::snapshot_environment();
    // ---- 界面风格(主题)切换的重启循环 ----
    // 风格改动牵动整体布局,无法热应用(见 theme::UiStyle)。用户在"外观"里换风格时,
    // 界面先关闭窗口,run_native 返回后由这里**立刻用新风格重新打开** ——
    // 表现出来就是"关一下 UI 再打开,确保完全切换完毕"。风格存放在 look.json,
    // 重启后 PadApp::new 自动读回,于是"上一次设的主题,下次启动还在"。
    let result = loop {
        let mut viewport = egui::ViewportBuilder::default()
            .with_inner_size([1180.0, 760.0])
            .with_min_inner_size([900.0, 600.0]);
        if let Some(icon) = app_icon() {
            viewport = viewport.with_icon(std::sync::Arc::new(icon));
        }
        let options = eframe::NativeOptions {
            viewport,
            ..Default::default()
        };
        let result = eframe::run_native(
            "scrcpy-pad 游戏控制台",
            options,
            Box::new(|cc| Ok(Box::new(app::PadApp::new(cc)))),
        );
        // 兜底恢复系统光标方案,避免异常退出路径把透明光标遗留给桌面。
        capture::set_cursor_visible_from_ui(true);
        if app::take_style_restart() {
            continue; // 风格切换:窗口已关,马上按新风格重开
        }
        break result;
    };
    // 关掉 GUI 窗口**必然**结束进程 —— 这不是想当然,是按 eframe 0.36 的实际路径核过的:
    // 主视口(ROOT)收到 CloseRequested 后,只要应用没有回 `ViewportCommand::CancelClose`,
    // eframe 就把 close 置真 -> `EventResult::CloseRequested` -> `save_and_destroy()`
    // (顺手调用 PadApp::on_exit 的幂等清理)-> `run_native` 返回,循环随即 break 到这里。
    // 本工程既不发 CancelClose,也没有"隐藏主窗但不退出"的路径:调试悬浮窗与截图小窗
    // 都是 `show_viewport_immediate` 的子视口,它们的 X 只关自己(app.rs 里各有处理)。
    // 唯一让循环继续的是 `take_style_restart()` 的**主动重启** —— 那是同一次进程内
    // 关窗重开,守卫与捕获层本就该继续持有,不是"关了还赖着"。
    capture::set_cursor_visible_from_ui(true);
    match result {
        Ok(()) => finish(0),
        Err(error) => {
            eprintln!("scrcpy-pad 退出错误: {error}");
            finish(1);
        }
    }
}

/// 已有实例在跑时的退出码(与"自检失败 = 1"分开:脚本/启动器能分辨
/// "起不来"和"跑失败"是两回事)。
const EXIT_ALREADY_RUNNING: i32 = 2;

/// **所有**退出路径的唯一收尾:刷轨迹 -> 还原定时器精度 -> 写"正常退出"标记 -> 退出。
///
/// 为什么必须只有这一处:收尾漏掉任何一句都有具体代价 —— 轨迹不刷盘(用户刚复现完
/// 就要拿这个文件)、定时器不还原(把整机计时精度一直抬高)、标记不写(下次启动
/// 误报"上次是崩溃或被强杀")。以前三个提前退出分支各抄一份,抄漏一句没人发现
/// (`selftest` 内部就曾直接 `process::exit`,跳过标记);现在 `--selftest` /
/// `--mask-selftest` / 单实例守卫 / 正常关闭 / 退出错误全走这里,新增退出路径
/// 也只能走这里。
fn finish(code: i32) -> ! {
    // 先收掉"手机被手触摸"监听子进程:Windows 不会随父进程退出杀子进程,
    // 不收就是设备上一个永远挂着的 `getevent`(用户明确要求零残留)。
    adb::stop_physical_touch_watches();
    trace::flush();
    timer::restore();
    diag::shutdown();
    std::process::exit(code)
}

/// 程序图标:编译期直接嵌入二进制,运行时不依赖任何外部图片文件
const APP_ICON_PNG: &[u8] = include_bytes!("../icons/scrcpy-pad.png");

/// 解码内嵌的程序图标;解码失败时返回 None,由系统使用默认图标
fn app_icon() -> Option<egui::IconData> {
    let img = image::load_from_memory(APP_ICON_PNG).ok()?;
    let rgba = img.to_rgba8();
    let (w, h) = rgba.dimensions();
    // 过大时缩到 256 以内,避免个别平台不接受超大图标
    let rgba = if w > 256 || h > 256 {
        let img2 = image::DynamicImage::ImageRgba8(rgba);
        img2.resize(256, 256, image::imageops::FilterType::Triangle)
            .to_rgba8()
    } else {
        rgba
    };
    let (w, h) = rgba.dimensions();
    Some(egui::IconData {
        rgba: rgba.into_raw(),
        width: w,
        height: h,
    })
}

/// 无界面自检:验证键盘捕获权限 / adb / scrcpy 定位 / 控制通道 / 协议注入(仅发无害 hover)
fn selftest() -> i32 {
    let mut failed = false;
    let mut check = |name: &str, ok: bool, detail: &str| {
        println!("[{}] {name} {detail}", if ok { "PASS" } else { "FAIL" });
        if !ok {
            failed = true;
        }
    };

    // 1. 键盘捕获权限
    #[cfg(target_os = "linux")]
    {
        let evdev_ok = std::fs::read_dir("/dev/input")
            .map(|rd| {
                rd.flatten()
                    .filter(|e| e.file_name().to_string_lossy().starts_with("event"))
                    .any(|e| std::fs::File::open(e.path()).is_ok())
            })
            .unwrap_or(false);
        check(
            "evdev 读取权限",
            evdev_ok,
            if evdev_ok {
                ""
            } else {
                "→ sudo usermod -aG input $USER 后重新登录"
            },
        );
    }
    #[cfg(windows)]
    check("键盘捕获(Windows 低级钩子)", true, "(Windows 无需特殊权限)");

    // 1b. 鼠标设备(FPS 瞄准依赖相对位移,须能被读到)
    #[cfg(target_os = "linux")]
    {
        let mice = evdev::enumerate()
            .filter(|(_, d)| {
                d.supported_relative_axes()
                    .map(|a| {

        K::ControlRight => 97,
        K::AltLeft => 56,
        K::AltRight => 100,
        K::SuperLeft => 125,
        K::SuperRight => 126,
        K::IntlBackslash => 86,
        K::BrowserBack => 158,
        // 符号键: 统一落到标准键盘的物理键位;只有在 physical_key 缺失时
        // 才会以逻辑键名走到这里(全局捕获始终按物理键位上报)
        K::Semicolon | K::Colon => 39,
        K::Quote => 40,
        K::Comma => 51,
        K::Minus => 12,
        K::Period => 52,
        K::Slash | K::Questionmark => 53,
        K::Backslash | K::Pipe => 43,
        K::Equals | K::Plus => 13,
        K::OpenBracket | K::OpenCurlyBracket => 26,
        K::CloseBracket | K::CloseCurlyBracket => 27,
        K::Backtick => 41,
        K::Exclamationmark => 2,
        _ => return None,
    })
}

impl PadApp {
    pub fn new(cc: &eframe::CreationContext<'_>) -> Self {
        install_cjk_font(&cc.egui_ctx);
        let (cap_tx, cap_rx) = channel::<CaptureEvent>();
        let (gui_tx, gui_rx) = channel::<CaptureEvent>();
        // Repair a stale blank system cursor if a previous process was killed
        // while cursor capture was active.
        crate::capture::set_cursor_visible_from_ui(true);

        // 程序级设置(scrcpy 三件套路径等):与 profile.yaml / look.json 同目录的 settings.json。
        // 有了它,scrcpy 目录即使不在程序同级,重启后也仍然记得,不必每次重新寻找。
        // 必须放在读取键位配置**之前**:里面还记着"上次选用的是哪一份配置"(W0-9)。
        let mut saved = settings::load().unwrap_or_default(); // 先留一份"文件里原本写了什么":关掉[记住路径]时写回的内容要以它为准,
        // 而且落盘判定也必须以磁盘上的真实内容为基准(否则"关掉开关"这一动作
        // 永远写不出去,下次启动又变回"记住")。
        let loaded_raw = saved.clone();
        // 日志级别:环境变量优先(临时排查不必改文件),否则用 settings.json 里的设置。
        // 放在这里是因为 diag 已经在 main() 最开始初始化好了,那时还没读到设置文件。
        if std::env::var(crate::diag::ENV_LEVEL).is_err() {
            crate::diag::set_level_from_str(&saved.log_level, "settings.json");
        }
        if !saved.remember_paths {
            // 用户关掉了"记住路径":不采用其中的路径,但仍保留启动参数一类的偏好
            saved.clear_paths();
        }
        let remembered = saved.clone();
        // 记住的路径可能早已被移动/删除:清掉死路径,但**保留它的位置线索**
        // (所在目录会记进 scrcpy_dir),启动时能在那一带重新找回 scrcpy
        if saved.sanitize() && saved.remember_paths {
            eprintln!(
                "[settings] 已修正 settings.json 里的路径(死路径转为目录线索): {}",
                settings::path().display()
            );
        }
        let (saved_args, legacy_mouse_args_removed) =
            sanitize_saved_scrcpy_args(&saved.scrcpy_args);
        let settings_cache = SettingsCache::new(loaded_raw.clone());

        // 配置文件里装的是多套"按键组合",`active` 指向上次用的那一套;
        // 引擎始终只认 `Shared::profile`(= 生效中的那套),组合表放在它旁边。
        //
        // 用户上次可能另选/新建过配置文件(位置记在 settings.json 的 `profile_path`):
        // 优先把它读回来。旧版这个路径只活在内存里 —— "我选的配置重启后不见了",
        // 程序每次都回到默认的 profile.yaml,用户只能一遍遍重选。
        // 读不回来时退回默认配置,并把原因上屏(不静默);
        // 记住的路径随即会被 settings 快照改成"实际在用"的默认路径(下次启动不再重复抱怨)。
        let default_profile_path = profile_path();
        let mut startup_notes: Vec<String> = Vec::new();
        let (doc, profile_path) = match remembered_profile_path(&saved) {
            Some(p) if p != default_profile_path => match read_profile_at(&p) {
                Ok(d) => {
                    startup_notes.push(format!("已恢复上次选用的配置: {}", p.display()));
                    (Some(d), p)
                }
                Err(e) => {
                    startup_notes.push(format!(
                        "上次选用的配置无法读取({e}),已改回默认配置: {}",
                        default_profile_path.display()
                    ));
                    let (d, notes) = load_profile();
                    startup_notes.extend(notes);
                    (d, default_profile_path)
                }
            },
            // 首次运行,或上次用的就是默认位置
            _ => {
                let (d, notes) = load_profile();
                startup_notes.extend(notes);
                (d, default_profile_path)
            }
        };
        let mut doc = doc.unwrap_or_default();
        doc.normalize();
        let mut profile = doc.active_profile().cloned().unwrap_or_default();
        // 外观(配色/密度/背景图)另有一份"程序自用"的缓存,与键位配置同目录。
        // 有了它,即使没点过[保存配置],重启后外观也保持上次调好的样子。
        let (cached_look, look_notes) = load_look_cache();
        startup_notes.extend(look_notes);
        if let Some(cached) = cached_look {
            profile.look = cached;
        }
        // 生效中的那套要与刚装载的 profile 对齐(外观缓存可能刚覆盖过它)
        if let Some(slot) = doc.schemes.get_mut(doc.active) {
            *slot = profile.clone();
        }
        // 界面风格(主题)是**界面级**设置:启动时从外观缓存里取一次,
        // 之后由 PadApp.style 持有并每帧回写(切换按键组合不会把它带走)。
        let ui_style = profile.look.style;

        let shared: SharedState = Arc::new(std::sync::Mutex::new(Shared {
            profile,
            enabled: false,
            control: None,
            aim_live: Default::default(),
            live: Default::default(),
            notices: Vec::new(),
            space_recheck: false,
            toolbar_release: false,
            // DF-5(engine 侧在跑):界面确认坐标空间变了之后置位,由引擎取走并
            // 抬掉所有按在旧空间里的触点(一次性请求;见 `Shared` 的注释)。
            space_changed_release: false,
            recoil_gear_req: None,
            schemes: doc.schemes.clone(),
            switch_keys: doc.switch_keys.clone(),
            fast_switch_enabled: doc.fast_switch_enabled,
            active_scheme: doc.active,
        }));

        // 输入捕获层(evdev)
        let (capture, capture_err) = match Capture::start(cap_tx) {
            Ok(c) => (Some(c), None),
            Err(e) => (None, Some(format!("{e:#}"))),
        };
        let grab_flag = capture
            .as_ref()
            .map(|c| c.grab.clone())
            .unwrap_or_else(|| Arc::new(false.into()));
        let swallow_flag = capture
            .as_ref()
            .map(|c| c.swallow.clone())
            .unwrap_or_else(|| Arc::new(0.into()));
        // 独占模式(B21-2/G-b):捕获层没起来时给空位图 + 开关关(照抄同款写法)
        let bound_keys_flag = capture
            .as_ref()
            .map(|c| c.bound_keys.clone())
            .unwrap_or_else(|| Arc::new(crate::capture::BoundKeys::new()));
        let swallow_bound_keys_flag = capture
            .as_ref()
            .map(|c| c.swallow_bound_keys.clone())
            .unwrap_or_else(|| Arc::new(false.into()));
        // 「FPS 鼠标隔膜」(2026-10-11):初值 false —— 程序刚起来绝不能吞鼠标。
        let mouse_shield_flag = capture
            .as_ref()
            .map(|c| c.mouse_shield.clone())
            .unwrap_or_else(|| Arc::new(false.into()));
        // G-c(钉住光标):初值 false —— 与捕获层里的初值一致,**由界面第一帧
        // 按设置写进去**。捕获层起来到第一帧之间那一小段宁可不钉,也不要
        // 在一个还没读设置的实例上先钉住。
        let clip_cursor_flag = capture
            .as_ref()
            .map(|c| c.clip_cursor.clone())
            .unwrap_or_else(|| Arc::new(false.into()));
        let mouse_grab_flag = capture
            .as_ref()
            .map(|c| c.mouse_grab.clone())
            .unwrap_or_else(|| Arc::new(false.into()));
        let cursor_hide_flag = capture
            .as_ref()
            .map(|c| c.cursor_hide.clone())
            .unwrap_or_else(|| Arc::new(false.into()));
        let mouse_found_flag = capture
            .as_ref()
            .map(|c| c.mouse_found.clone())
            .unwrap_or_else(|| Arc::new(false.into()));
        let hook_lag_flag = capture
            .as_ref()
            .map(|c| c.hook_lag.clone())
            .unwrap_or_else(|| Arc::new(false.into()));
        let hb_flag = capture
            .as_ref()
            .map(|c| c.hb_state.clone())
            .unwrap_or_else(|| Arc::new(0.into()));
        let hook_ok_flag = capture
            .as_ref()
            .map(|c| c.hook_ok.clone())
            .unwrap_or_else(|| Arc::new(0.into()));

        // 映射引擎线程(鼠标捕获状态由引擎统一维护,避免与 UI 帧率不同步)
        {
            let shared = shared.clone();
            let mouse_grab = mouse_grab_flag.clone();
            let cursor_hide = cursor_hide_flag.clone();
            std::thread::spawn(move || {
                // 事件分发主线程:满载机器上必须优先于普通后台任务拿到 CPU。
                crate::priority::boost(crate::priority::Class::AboveNormal);
                crate::engine::run(shared, cap_rx, gui_tx, mouse_grab, cursor_hide)
            });
        }

        // 自动寻找 scrcpy 与 server:先用上次记住的路径/目录,再自动寻找
        let (scrcpy_path, server_path, version, found_msg) = {
            let (remembered_exe, note) = locate_remembered_scrcpy(&saved);
            let from_memory = remembered_exe.is_some();
            let exe = match remembered_exe {
                Some(p) => Some(p),
                None => adb::find_scrcpy(),

                // 位移是整批聚合后再发的,记下最后一条相对轴事件的时刻
                let mut last_axis_at = inst_anchor;
                for ev in events {
                    let at = event_time(&ev, sys_anchor, inst_anchor);
                    match ev.destructure() {
                        evdev::EventSummary::Key(_, key, value) => {
                            // value: 0=抬起 1=按下 2=自动重复
                            if value == 2 {
                                // 自动重复不转发(引擎用上升沿收口),但它证明
                                // "这个键此刻确实按着",是天然的心跳,留着无坏处
                                continue;
                            }
                            let pressed = value == 1;
                            {
                                let mut s = lock(&st);
                                if pressed {
                                    s.delivered.insert(key.0);
                                } else {
                                    s.delivered.remove(&key.0);
                                }
                            }
                            let _ = tx.send(CaptureEvent::Button {
                                code: key.0,
                                pressed,
                                at,
                            });
                        }
                        evdev::EventSummary::RelativeAxis(_, axis, value) if mouse => {
                            last_axis_at = at;
                            if axis == evdev::RelativeAxisCode::REL_X {
                                dx += value as f32;
                            } else if axis == evdev::RelativeAxisCode::REL_Y {
                                dy += value as f32;
                            } else if axis == evdev::RelativeAxisCode::REL_WHEEL
                                || axis == evdev::RelativeAxisCode::REL_HWHEEL
                            {
                                if value != 0 {
                                    let code = match (axis, value.is_positive()) {
                                        (evdev::RelativeAxisCode::REL_WHEEL, true) => {
                                            crate::keymap::BTN_WHEEL_UP
                                        }
                                        (evdev::RelativeAxisCode::REL_WHEEL, false) => {
                                            crate::keymap::BTN_WHEEL_DOWN
                                        }
                                        (evdev::RelativeAxisCode::REL_HWHEEL, true) => {
                                            crate::keymap::BTN_WHEEL_RIGHT
                                        }
                                        _ => crate::keymap::BTN_WHEEL_LEFT,
                                    };
                                    for _ in 0..value.unsigned_abs().min(10) {
                                        let _ = tx.send(CaptureEvent::Button {
                                            code,
                                            pressed: true,
                                            at,
                                        });
                                        let _ = tx.send(CaptureEvent::Button {
                                            code,
                                            pressed: false,
                                            at,
                                        });
                                    }
                                }
                            }
                        }
                        _ => {}
                    }
                }
                if dx != 0.0 || dy != 0.0 {
                    let _ = tx.send(CaptureEvent::Motion {
                        dx,
                        dy,
                        at: last_axis_at,
                    });
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                std::thread::sleep(Duration::from_millis(2));
            }
            Err(e) => {
                hard_errors += 1;
                if hard_errors == 1 || hard_errors == 20 {
                    diag_warn!(
                        "capture",
                        "读取 {} 出错(第 {} 次): {e} (errno {:?})",
                        path.display(),
                        hard_errors,
                        e.raw_os_error()
                    );
                }
                if hard_errors >= 20 {
                    // 设备确实没了:登记注销,让重扫有机会重新接管。
                    // 注销时校验令牌,避免把复用同一节点名的新设备登记抹掉。
                    {
                        let mut s = lock(&st);
                        if s.alive.get(&path).map(|x| x.token) == Some(token) {
                            s.alive.remove(&path);
                            s.truth_devs.remove(&path);
                        }
                    }
                    diag_warn!(
                        "capture",
                        "放弃 {} 「{}」(连续 {hard_errors} 次读取失败;它被拔掉或复位了,重扫会重新接管)",
                        path.display(),
                        &dev_name
                    );
                    return;
                }
                std::thread::sleep(Duration::from_millis(50));
            }
        }
    }
    if grabbed {
        let _ = device.ungrab();
    }
}

/// 后台监管线程:热插拔重扫 + 丢失 release 的自愈
fn supervisor(
    st: Shared,
    grab: Arc<AtomicBool>,
    mouse_grab: Arc<AtomicBool>,
    mouse_found: Arc<AtomicBool>,
    stop: Arc<AtomicBool>,
    tx: Sender<CaptureEvent>,
) {
    let mut tick: u32 = 0;
    while !stop.load(Ordering::Relaxed) {
        std::thread::sleep(Duration::from_millis(HEARTBEAT_MS));
        if stop.load(Ordering::Relaxed) {
            break;
        }
        tick = tick.wrapping_add(1);
        if tick % RECONCILE_TICKS == 0 {
            reconcile_keys(&st, &tx);
        }
        if tick % RESCAN_TICKS == 0 {
            let (kb, mice, denied) = scan(&st, &grab, &mouse_grab, &stop, &tx);
            let had = mouse_found.load(Ordering::Relaxed);
            mouse_found.store(mice > 0, Ordering::Relaxed);
            if had && mice == 0 {
                diag_warn!(
                    "capture",
                    "鼠标设备已全部消失(FPS 瞄准将不可用),等待重新插入"
                );
            } else if !had && mice > 0 {
                diag_info!("capture", "检测到鼠标设备({mice} 个),FPS 瞄准现在可用");
            }
            if denied > 0 && kb == 0 && mice == 0 {
                diag_warn!("capture", "当前没有任何可用输入设备({denied} 个节点打不开)");
            }
        }
    }
    diag_info!("capture", "捕获层监管线程退出");
}

