/// 捕获层的一个按键事件(键盘与鼠标键同码空间)。
pub fn button(code: u16, pressed: bool) {
    if !enabled() {
        return;
    }
    write_line(format!(
        r#"{{"t":{},"k":"in","e":"btn","code":{},"down":{}}}"#,
        now_ms(),
        code,
        pressed
    ));
}

/// 捕获层的一次鼠标相对位移(设备计数,非像素)。
pub fn motion(dx: f32, dy: f32) {
    if !enabled() {
        return;
    }
    write_line(format!(
        r#"{{"t":{},"k":"in","e":"motion","dx":{},"dy":{}}}"#,
        now_ms(),
        dx,
        dy
    ));
}

