use std::ffi::CString;
use std::io::Write;
use std::os::unix::io::AsRawFd;

#[repr(C)]
struct InputId { bustype: u16, vendor: u16, product: u16, version: u16 }
#[repr(C)]
struct UinputSetup { id: InputId, name: [u8; 80], ff_effects_max: u32 }
#[repr(C)]
struct TimeVal { sec: i64, usec: i64 }
#[repr(C)]
struct InputEvent { time: TimeVal, type_: u16, code: u16, value: i32 }

extern "C" {
    fn ioctl(fd: i32, req: u64, ...) -> i32;
    fn clock_gettime(clk: i32, tp: *mut TimeVal) -> i32;
}

const UI_SET_EVBIT: u64 = 0x4004_5564;
const UI_SET_KEYBIT: u64 = 0x4004_5565;
const UI_SET_RELBIT: u64 = 0x4004_5566;
const UI_DEV_SETUP: u64 = 0x405c_5503;
const UI_DEV_CREATE: u64 = 0x0000_5501;
const UI_DEV_DESTROY: u64 = 0x0000_5502;

const EV_SYN: u16 = 0;
const EV_KEY: u16 = 1;
const EV_REL: u16 = 2;
const SYN_REPORT: u16 = 0;
const REL_X: u16 = 0;
const REL_Y: u16 = 1;

const KEY_A: u16 = 30;
const KEY_F8: u16 = 66;
const KEY_ESC: u16 = 1;

fn create(name: &str, keys: &[u16], rels: bool) -> i32 {
    let path = CString::new("/dev/uinput").unwrap();
    let fd = unsafe { libc_open(path.as_ptr(), 2 /*O_RDWR*/) };
    assert!(fd >= 0, "open /dev/uinput 失败");
    let setup = UinputSetup {
        id: InputId { bustype: 0x03, vendor: 0x1234, product: 0x5678, version: 1 },
        name: {
            let mut b = [0u8; 80];
            let n = name.as_bytes();
            b[..n.len().min(79)].copy_from_slice(&n[..n.len().min(79)]);
            b
        },
        ff_effects_max: 0,
    };
    assert_eq!(unsafe { ioctl(fd, UI_DEV_SETUP, &setup as *const UinputSetup) }, 0, "UI_DEV_SETUP 失败");
    assert_eq!(unsafe { ioctl(fd, UI_SET_EVBIT, EV_KEY as u64) }, 0);
    if rels {
        assert_eq!(unsafe { ioctl(fd, UI_SET_EVBIT, EV_REL as u64) }, 0);
        for r in [REL_X, REL_Y] {
            assert_eq!(unsafe { ioctl(fd, UI_SET_RELBIT, r as u64) }, 0);
        }
    }
    for k in keys {
        assert_eq!(unsafe { ioctl(fd, UI_SET_KEYBIT, *k as u64) }, 0, "UI_SET_KEYBIT {k} 失败");
    }
    assert_eq!(unsafe { ioctl(fd, UI_DEV_CREATE, 0u64) }, 0, "UI_DEV_CREATE 失败");
    fd
}

fn emit(fd: i32, type_: u16, code: u16, value: i32) {
    let mut ts = TimeVal { sec: 0, usec: 0 };
    unsafe { clock_gettime(1 /*CLOCK_MONOTONIC*/, &mut ts) };
    let ev = InputEvent { time: ts, type_, code, value };
    let n = unsafe { libc_write(fd, &ev as *const InputEvent as *const u8, std::mem::size_of::<InputEvent>()) };
    assert_eq!(n as usize, std::mem::size_of::<InputEvent>(), "写事件失败");
}

fn syn(fd: i32) { emit(fd, EV_SYN, SYN_REPORT, 0); }

extern "C" {
    fn open(path: *const i8, flags: i32, ...) -> i32;
    fn write(fd: i32, buf: *const u8, n: usize) -> isize;
}
fn libc_open(p: *const i8, f: i32) -> i32 { unsafe { open(p, f) } }
fn libc_write(fd: i32, b: *const u8, n: usize) -> isize { unsafe { write(fd, b, n) } }

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mode = args.get(1).map(|s| s.as_str()).unwrap_or("kbd-loop");
    match mode {
        // 建一把虚拟键盘并常驻,--out 指定的文件里写设备名,便于外部确认
        "kbd-script" => {
            let keys: Vec<u16> = (KEY_A..=KEY_A + 25).chain([KEY_F8, KEY_ESC, 28, 57, 14].into_iter()).collect();
            let fd = create("scrcpy-pad probe kbd", &keys, false);
            let path = find_self_path();
            println!("{}", path);
            std::io::stdout().flush().ok();
            std::thread::sleep(std::time::Duration::from_millis(1500)); // 等 udev 建节点
            // 1) 单次 A 按下/抬起
            emit(fd, EV_KEY, KEY_A, 1); syn(fd);
            std::thread::sleep(std::time::Duration::from_millis(120));
            emit(fd, EV_KEY, KEY_A, 0); syn(fd);
            std::thread::sleep(std::time::Duration::from_millis(300));
            // 2) F8(映射总开关)按一下
            emit(fd, EV_KEY, KEY_F8, 1); syn(fd);
            std::thread::sleep(std::time::Duration::from_millis(120));
            emit(fd, EV_KEY, KEY_F8, 0); syn(fd);
            std::thread::sleep(std::time::Duration::from_millis(800));
            // 3) 1kHz 连打 1.5 秒,用于量捕获批的间距分布
            for _ in 0..1500 {
                emit(fd, EV_KEY, KEY_A, 1); syn(fd);
                emit(fd, EV_KEY, KEY_A, 0); syn(fd);
                std::thread::sleep(std::time::Duration::from_micros(1000));
            }
            println!("INJECT_DONE");
            std::io::stdout().flush().ok();
            std::thread::sleep(std::time::Duration::from_secs(2));
            unsafe { ioctl(fd, UI_DEV_DESTROY, 0u64) };
        }
        // 建一把虚拟鼠标并常驻,报告路径,用于热插拔测试
        "mouse-idle" => {
            let fd = create("scrcpy-pad probe mouse", &[0x110, 0x111, 0x112], true);
            println!("{}", find_self_path());
            std::io::stdout().flush().ok();
            std::thread::sleep(std::time::Duration::from_secs(6));
            unsafe { ioctl(fd, UI_DEV_DESTROY, 0u64) };
        }
        _ => {
            eprintln!("用法: uinput_probe kbd-script | mouse-idle");
            std::process::exit(2);
        }
    }
}

/// 找刚建的那个 event 节点(按 sysfs name 匹配)
fn find_self_path() -> String {
    for entry in std::fs::read_dir("/dev/input").unwrap().flatten() {
        let p = entry.path();
        let n = p.file_name().unwrap().to_string_lossy().to_string();
        if !n.starts_with("event") { continue; }
        let namefile = format!("/sys/class/input/{n}/device/name");
        if let Ok(s) = std::fs::read_to_string(&namefile) {
            if s.starts_with("scrcpy-pad probe") {
                return p.display().to_string();
            }
        }
    }
    String::from("(not found)")
}
