//! 同一个 uinput 设备、同一注入速率,量"内核事件时刻 -> 用户态拿到"的延迟。
use std::io::Read;
use std::os::unix::io::AsRawFd;
use std::time::{Duration, Instant};

#[repr(C)]
struct InputId { bustype: u16, vendor: u16, product: u16, version: u16 }
#[repr(C)]
struct UinputSetup { id: InputId, name: [u8; 80], ff_effects_max: u32 }
#[repr(C)]
struct TimeVal { sec: i64, usec: i64 }
#[repr(C)]
struct InputEvent { time: TimeVal, type_: u16, code: u16, value: i32 }
#[repr(C)]
struct PollFd { fd: i32, events: i16, revents: i16 }

extern "C" {
    fn ioctl(fd: i32, req: u64, ...) -> i32;
    fn clock_gettime(clk: i32, tp: *mut TimeVal) -> i32;
    fn poll(fds: *mut PollFd, n: u64, timeout: i32) -> i32;
    #[link_name = "open"]
    fn c_open(path: *const i8, flags: i32, ...) -> i32;
    #[link_name = "write"]
    fn c_write(fd: i32, buf: *const u8, n: usize) -> isize;
    #[link_name = "read"]
    fn c_read(fd: i32, buf: *mut u8, n: usize) -> isize;
    #[link_name = "fcntl"]
    fn c_fcntl(fd: i32, cmd: i32, ...) -> i32;
}

const UI_SET_EVBIT: u64 = 0x40045564;
const UI_SET_KEYBIT: u64 = 0x40045565;
const UI_DEV_SETUP: u64 = 0x405c5503;
const UI_DEV_CREATE: u64 = 0x00005501;
const UI_DEV_DESTROY: u64 = 0x00005502;
const EV_SYN: u16 = 0; const EV_KEY: u16 = 1; const SYN_REPORT: u16 = 0; const KEY_A: u16 = 30;
const POLLIN: i16 = 1; const O_RDWR: i32 = 2; const O_NONBLOCK: i32 = 0o4000; const F_SETFL: i32 = 4;

fn create() -> i32 {
    let p = std::ffi::CString::new("/dev/uinput").unwrap();
    let fd = unsafe { c_open(p.as_ptr(), O_RDWR) };
    assert!(fd >= 0);
    let mut name = [0u8; 80];
    name[..22].copy_from_slice(b"scrcpy-pad lat bench");
    let setup = UinputSetup { id: InputId { bustype: 3, vendor: 0x1234, product: 0x9999, version: 1 }, name, ff_effects_max: 0 };
    unsafe {
        assert_eq!(ioctl(fd, UI_DEV_SETUP, &setup as *const UinputSetup), 0);
        assert_eq!(ioctl(fd, UI_SET_EVBIT, EV_KEY as u64), 0);
        assert_eq!(ioctl(fd, UI_SET_KEYBIT, KEY_A as u64), 0);
        assert_eq!(ioctl(fd, UI_DEV_CREATE, 0u64), 0);
    }
    fd
}

fn devnode() -> String {
    for e in std::fs::read_dir("/dev/input").unwrap().flatten() {
        let p = e.path();
        let n = p.file_name().unwrap().to_string_lossy().to_string();
        if !n.starts_with("event") { continue; }
        if std::fs::read_to_string(format!("/sys/class/input/{n}/device/name"))
            .map(|s| s == "scrcpy-pad lat bench\n" || s == "scrcpy-pad lat bench")
            .unwrap_or(false) { return p.display().to_string(); }
    }
    panic!("找不到 bench 设备节点");
}

fn now_mono_ns() -> i64 {
    let mut t = TimeVal { sec: 0, usec: 0 };
    unsafe { clock_gettime(1, &mut t) };
    t.sec * 1_000_000_000 + t.usec * 1_000
}

fn emit(fd: i32) {
    let mut ts = TimeVal { sec: 0, usec: 0 };
    unsafe { clock_gettime(1, &mut ts) };
    let ev = InputEvent { time: ts, type_: EV_KEY, code: KEY_A, value: 1 };
    unsafe { c_write(fd, &ev as *const InputEvent as *const u8, 24) };
    let syn = InputEvent { time: ts, type_: EV_SYN, code: SYN_REPORT, value: 0 };
    unsafe { c_write(fd, &syn as *const InputEvent as *const u8, 24) };
    let ev = InputEvent { time: ts, type_: EV_KEY, code: KEY_A, value: 0 };
    unsafe { c_write(fd, &ev as *const InputEvent as *const u8, 24) };
}

/// 读一批,返回 (最旧事件的内核时刻, 本条位置), 用 read 系统调用模拟 evdev fetch_events
fn read_batch(fd: i32, buf: &mut [u8]) -> (i64, usize) {
    let n = unsafe { c_read(fd, buf.as_mut_ptr(), buf.len()) };
    if n <= 0 { return (0, 0); }
    let cnt = n as usize / 24;
    let first = unsafe { &*(buf.as_ptr() as *const InputEvent) };
    (first.time.sec * 1_000_000_000 + first.time.usec * 1_000, cnt)
}

fn run(mode: &str, rate_us: u64, n: usize) -> Vec<f64> {
    let wfd = create();
    std::thread::sleep(Duration::from_millis(600));
    let path = devnode();
    let p = std::ffi::CString::new(path).unwrap();
    let rfd = unsafe { c_open(p.as_ptr(), O_RDWR | O_NONBLOCK) };
    assert!(rfd >= 0, "open 设备失败");
    let mut buf = [0u8; 24 * 64];
    // 清掉创建时可能残留的事件
    while read_batch(rfd, &mut buf).1 > 0 {}

    let injector = std::thread::spawn(move || {
        std::thread::sleep(Duration::from_millis(200));
        for _ in 0..n {
            emit(wfd);
            std::thread::sleep(Duration::from_micros(rate_us));
        }
    });

    let mut lat = Vec::new();
    let deadline = Instant::now() + Duration::from_secs(30);
    while lat.len() < n && Instant::now() < deadline {
        match mode {
            "sleep2ms" => {
                let (t0, cnt) = read_batch(rfd, &mut buf);
                if cnt == 0 { std::thread::sleep(Duration::from_millis(2)); continue; }
                let now = now_mono_ns();
                lat.push((now - t0) as f64 / 1e6);
            }
            "poll" => {
                let mut pfd = PollFd { fd: rfd, events: POLLIN, revents: 0 };
                let r = unsafe { poll(&mut pfd, 1, -1) };
                if r <= 0 { continue; }
                let (t0, cnt) = read_batch(rfd, &mut buf);
                if cnt == 0 { continue; }
                let now = now_mono_ns();
                lat.push((now - t0) as f64 / 1e6);
            }
            _ => panic!("unknown"),
        }
    }
    let _ = injector.join();
    unsafe { ioctl(wfd, UI_DEV_DESTROY, 0u64) };
    lat
}

fn stat(mut v: Vec<f64>) -> String {
    if v.is_empty() { return "空".into(); }
    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let n = v.len();
    format!("n={n} p50={:.3} p90={:.3} p99={:.3} max={:.3} ms", v[n/2], v[n*90/100], v[n*99/100], v[n-1])
}

fn main() {
    let n = 800;
    for rate in [1000u64, 4000] {
        let a = run("sleep2ms", rate, n);
        let b = run("poll", rate, n);
        println!("注入间隔 {rate}us(每 {rate}us 一个 A 按下+抬起)");
        println!("  现状 非阻塞+sleep(2ms): {}", stat(a));
        println!("  poll(2) 阻塞等         : {}", stat(b));
    }
}
EOF
