#[repr(C)] #[derive(Clone,Copy)] struct Ev { t: TimeVal, ty: u16, c: u16, v: i32 }
#[repr(C)] struct PollFd { fd: i32, e: i16, r: i16 }
extern "C" {
  fn ioctl(fd: i32, req: u64, ...) -> i32;
  fn clock_gettime(c: i32, t: *mut TimeVal) -> i32;
  fn poll(f: *mut PollFd, n: u64, t: i32) -> i32;
  #[link_name="open"] fn o(p: *const i8, f: i32, ...) -> i32;
  #[link_name="write"] fn w(fd: i32, b: *const u8, n: usize) -> isize;
  #[link_name="read"] fn r(fd: i32, b: *mut u8, n: usize) -> isize;
  #[link_name="fcntl"] fn fcntl(fd: i32, c: i32, ...) -> i32;
}
fn clk(c: i32) -> TimeVal { let mut t = TimeVal{sec:0,usec:0}; unsafe { clock_gettime(c, &mut t) }; t }
fn main(){
  let p = std::ffi::CString::new("/dev/uinput").unwrap();
  let fd = unsafe { o(p.as_ptr(), 2) };
  let mut name=[0u8;80]; name[..9].copy_from_slice(b"lat-t2dev");
  let s = UinputSetup{ id: InputId{b:3,v:0x1234,p:0x9998,ver:1}, name, ff:0 };
  unsafe { ioctl(fd,0x405c5503,&s as *const _); ioctl(fd,0x40045564,1u64); ioctl(fd,0x40045565,30u64); ioctl(fd,0x00005501,0u64); }
  std::thread::sleep(std::time::Duration::from_millis(500));
  let mut dev=String::new();
  for e in std::fs::read_dir("/dev/input").unwrap().flatten(){ let q=e.path(); let n=q.file_name().unwrap().to_string_lossy().to_string(); if !n.starts_with("event"){continue;}
    if std::fs::read_to_string(format!("/sys/class/input/{n}/device/name")).map(|x|x.trim()=="lat-t2dev").unwrap_or(false){ dev=q.display().to_string(); } }
  println!("dev={dev}");
  let cp=std::ffi::CString::new(dev).unwrap();
  let rfd=unsafe{ o(cp.as_ptr(), 2|0o4000) };
  unsafe { fcntl(rfd, 4, 0o4000) };
  std::thread::sleep(std::time::Duration::from_millis(200));
  let mut buf=[0u8;24*64];
  while unsafe{ r(rfd, buf.as_mut_ptr(), buf.len()) } > 0 {}
  let rt = clk(0); let mt = clk(1);
  println!("before write: REALTIME={}.{:06} MONOTONIC={}.{:06}", rt.sec, rt.usec, mt.sec, mt.usec);
  // write with timestamp 0
  let ev = Ev{ t: TimeVal{sec:0,usec:0}, ty:1, c:30, v:1 };
  unsafe { w(fd, &ev as *const _ as *const u8, 24) };
  let syn = Ev{ t: TimeVal{sec:0,usec:0}, ty:0, c:0, v:0 };
  unsafe { w(fd, &syn as *const _ as *const u8, 24) };
  std::thread::sleep(std::time::Duration::from_millis(100));
  let mut pf=PollFd{fd:rfd,e:1,r:0};
  unsafe { poll(&mut pf,1,500) };
  let n = unsafe{ r(rfd, buf.as_mut_ptr(), buf.len()) };
  println!("read n={n}");
  let first = unsafe { &*(buf.as_ptr() as *const Ev) };
  println!("event time: {}.{:06}  ty={} c={} v={}", first.t.sec, first.t.usec, first.ty, first.c, first.v);
  let rt2=clk(0); let mt2=clk(1);
  println!("after  read: REALTIME={}.{:06} MONOTONIC={}.{:06}", rt2.sec, rt2.usec, mt2.sec, mt2.usec);
  unsafe { ioctl(fd,0x00005502,0u64) };
}
EOF
