//! 第 19 条 A/B:非阻塞 read + sleep(2ms)(生产现状) vs poll(2) 阻塞等。
//! 同一进程内用 Instant 量"写入完成 -> 读到"的端到端等待延迟,规避时钟域问题。
use std::collections::VecDeque;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

#[repr(C)] struct InputId { b: u16, v: u16, p: u16, ver: u16 }
#[repr(C)] struct UinputSetup { id: InputId, name: [u8; 80], ff: u32 }
#[repr(C)] #[derive(Clone, Copy)] struct TimeVal { sec: i64, usec: i64 }
#[repr(C)] #[derive(Clone, Copy)] struct Ev { t: TimeVal, ty: u16, c: u16, v: i32 }
#[repr(C)] struct PollFd { fd: i32, e: i16, r: i16 }

extern "C" {
    fn ioctl(fd: i32, req: u64, ...) -> i32;
    fn clock_gettime(c: i32, t: *mut TimeVal) -> i32;
    fn poll(f: *mut PollFd, n: u64, t: i32) -> i32;
    #[link_name = "open"] fn c_open(p: *const i8, f: i32, ...) -> i32;
    #[link_name = "write"] fn c_write(fd: i32, b: *const u8, n: usize) -> isize;
    #[link_name = "read"] fn c_read(fd: i32, b: *mut u8, n: usize) -> isize;
}

fn create(name_tag: &str) -> i32 {
    let p = std::ffi::CString::new("/dev/uinput").unwrap();
    let fd = unsafe { c_open(p.as_ptr(), 2) };
    assert!(fd >= 0, "open /dev/uinput");
    let mut name = [0u8; 80];
    let nb = name_tag.as_bytes();
    name[..nb.len().min(79)].copy_from_slice(&nb[..nb.len().min(79)]);
