//! 第 1 条 EVIOCGRAB 的独立性证明:进程 A grab 后,进程 B 读同一节点是否被拒。
use std::time::Duration;
extern "C" {
    fn ioctl(fd: i32, req: u64, ...) -> i32;
    #[link_name = "open"] fn c_open(p: *const i8, f: i32, ...) -> i32;
    #[link_name = "read"] fn c_read(fd: i32, b: *mut u8, n: usize) -> isize;
    #[link_name = "close"] fn c_close(fd: i32) -> i32;
}
const O_RDWR: i32 = 2;
const O_NONBLOCK: i32 = 0o4000;
const EVIOCGRAB: u64 = 0x40044590; // _IOW('E', 0x90, int)

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dev = args.get(1).cloned().unwrap_or("/dev/input/event3".into());
    let mode = args.get(2).cloned().unwrap_or("reader".into());
    let path = std::ffi::CString::new(dev.clone()).unwrap();
    let fd = unsafe { c_open(path.as_ptr(), O_RDWR | O_NONBLOCK) };
    if fd < 0 { eprintln!("open {dev} 失败 (errno 见下)"); std::process::exit(3); }
    match mode.as_str() {
        "grab" => {
            let one: i32 = 1;
            let r = unsafe { ioctl(fd, EVIOCGRAB, &one as *const i32) };
            println!("GRAB dev={dev} ret={r} errno={}", std::io::Error::last_os_error());
            if r == 0 {
                std::thread::sleep(Duration::from_secs(6));
                let zero: i32 = 0;
                unsafe { ioctl(fd, EVIOCGRAB, &zero as *const i32) };
                println!("UNGRAB");
            }
        }
        _ => {
            // 读设备 2 秒,统计拿到的事件数与 errno
            let mut buf = [0u8; 24 * 64];
            let t0 = std::time::Instant::now();
            let mut total = 0usize;
            let mut eagain = 0;
            let mut last_err = String::new();
            while t0.elapsed() < Duration::from_secs(2) {
                let n = unsafe { c_read(fd, buf.as_mut_ptr(), buf.len()) };
                if n > 0 { total += n as usize / 24; }
                else if n == 0 { break; }
                else {
                    let e = std::io::Error::last_os_error();
                    if e.kind() == std::io::ErrorKind::WouldBlock { eagain += 1; }
                    last_err = format!("{e}");
                }
                std::thread::sleep(Duration::from_millis(5));
            }
            unsafe { c_close(fd) };
            println!("READER dev={dev} events={total} would_block={eagain} last_err={last_err}");
        }
    }
}
EOF
