    /// 补发抬起并同步本地"已上报"集合
    fn release_all<I: IntoIterator<Item = u16>>(st: &Shared, tx: &Sender<CaptureEvent>, codes: I) {
        for code in codes {
            // 合成事件:没有"事件时刻",按发出时刻计(W1-1)
            let _ = tx.send(CaptureEvent::Button {
                code,
                pressed: false,
                at: Instant::now(),
