fn by_id_map() -> HashMap<std::ffi::OsString, String> {
    let mut out = HashMap::new();
    let Ok(rd) = std::fs::read_dir("/dev/input/by-id") else {
        return out;
    };
    for entry in rd.flatten() {
        let link_name = entry.file_name().to_string_lossy().into_owned();
        let Ok(target) = std::fs::read_link(entry.path()) else {
            continue;
        };
        let Some(node) = target.file_name() else {
            continue;
        };
        // 同一台设备常有 `-event-mouse` / `-event-kbd` / `-hidraw` 多条链接;
        // 只认 event 那条,并且让"每台设备只留一条"(后者覆盖前者,反正
        // 它们指向同一个节点,名字差别只在后缀)。
        if !node.to_string_lossy().starts_with("event") {
            continue;
        }
        out.insert(node.to_os_string(), link_name);
    }
    out
