//! 端到端:确认映射开启+grab 时,**另一个进程**读不到该键盘的事件。
//! 用法: grab_e2e <devnode> <listen_ms>
extern "C" {
    fn open(p: *const i8, f: i32, ...) -> i32;
    fn read(fd: i32, b: *mut u8, n: usize) -> isize;
    fn close(fd: i32) -> i32;
}
fn main() {
    let a: Vec<String> = std::env::args().collect();
    let dev = a.get(1).cloned().unwrap_or("/dev/input/event3".into());
    let ms: u64 = a.get(2).and_then(|s| s.parse().ok()).unwrap_or(4000);
    let p = std::ffi::CString::new(dev.clone()).unwrap();
    let fd = unsafe { open(p.as_ptr(), 2 | 0o4000) };
    if fd < 0 { println!("OPENFAIL {dev}"); return; }
    let mut buf = [0u8; 24 * 64];
    let t0 = std::time::Instant::now();
    let (mut got, mut eagain) = (0usize, 0usize);
    while t0.elapsed().as_millis() < ms as u128 {
        let n = unsafe { read(fd, buf.as_mut_ptr(), buf.len()) };
        if n > 0 { got += n as usize / 24; } else if n == 0 { break; }
        else if std::io::Error::last_os_error().kind() == std::io::ErrorKind::WouldBlock { eagain += 1; }
        std::thread::sleep(std::time::Duration::from_millis(2));
    }
    unsafe { close(fd) };
    println!("LISTEN {dev} events={got} wouldblock={eagain}");
}
