use std::fs::{File, OpenOptions};
use std::io::Read;

fn main() {
    let path = std::env::temp_dir().join("lockprobe-test.lock");
    let _ = std::fs::remove_file(&path);
    let mut a = OpenOptions::new().read(true).write(true).create(true).truncate(false).open(&path).unwrap();
    a.try_lock().expect("first lock");
