//! 复现:多线程并发对**不同**锁文件 try_lock,是否会互相影响?
use std::fs::OpenOptions;

fn main() {
    let dir = std::env::temp_dir();
    std::thread::scope(|s| {
        for _ in 0..8 {
            s.spawn(|| {
                for _ in 0..40 {
                    let path = dir.join(format!("lpar-{}-{:?}.lock", std::process::id(), std::thread::current().id()));
                    let _ = std::fs::remove_file(&path);
                    let a = OpenOptions::new().read(true).write(true).create(true).truncate(false).open(&path).unwrap();
                    a.try_lock().expect("A 锁不到");
                    drop(a);
                    let b = OpenOptions::new().read(true).write(true).create(true).truncate(false).open(&path).unwrap();
                    if b.try_lock().is_err() {
                        println!("!!! drop 之后仍锁不到: {:?}", path);
                        std::process::exit(1);
                    }
                    let _ = std::fs::remove_file(&path);
                }
            });
        }
    });
    println!("PARALLEL_OK");
}
EOF
