//! 精确复现 instance::imp::acquire_path 的序列(含 WouldBlock 分支里的 holder_pid)
use std::fs::{File, OpenOptions};
use std::io::{Read, Seek, SeekFrom, Write};

fn acquire(path: &std::path::Path) -> Result<File, String> {
    let mut file = OpenOptions::new().read(true).write(true).create(true).truncate(false)
        .open(path).map_err(|e| e.to_string())?;
    match file.try_lock() {
        Ok(()) => {
            let _ = file.set_len(0);
            let _ = file.seek(SeekFrom::Start(0));
            let _ = write!(file, "{}", std::process::id());
            let _ = file.flush();
            Ok(file)
        }
        Err(e) => {
            // 模拟 holder_pid:另开句柄读
            let mut t = String::new();
            let _ = File::open(path).and_then(|mut f| f.read_to_string(&mut t));
            Err(format!("{e:?} holder={t:?}"))
        }
    }
}

fn main() {
    let dir = std::env::temp_dir();
    const RUNS: usize = 3000;
    for i in 0..RUNS {
        let path = dir.join(format!("lrepro-{}.lock", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let first = acquire(&path).expect("first");
        let second = acquire(&path);
        assert!(second.is_err(), "run {i}: 第二个居然拿到了锁");
        drop(first);
        match acquire(&path) {
            Ok(_) => {}
            Err(e) => {
                println!("!!! run {i}: drop 之后锁不到: {e}");
                std::process::exit(1);
            }
        }
        let _ = std::fs::remove_file(&path);
    }
    println!("REPRO_OK {RUNS} runs");
}
EOF
