//! 复现根因:同一进程里两个"测试"用**同一个**锁文件路径,会互相抢
use std::fs::OpenOptions;
use std::io::{Seek, SeekFrom, Write};

fn acquire(path: &std::path::Path) -> Result<std::fs::File, ()> {
    let mut f = OpenOptions::new().read(true).write(true).create(true).truncate(false).open(path).unwrap();
    f.try_lock().map(|_| { let _ = f.set_len(0); let _ = f.seek(SeekFrom::Start(0)); let _ = write!(f, "{}", std::process::id()); f }).map_err(|_| ())
}

fn main() {
    let path = std::env::temp_dir().join("collide.lock");
    let _ = std::fs::remove_file(&path);
    let p1 = path.clone();
    let p2 = path.clone();
    let c = std::sync::Arc::new(std::sync::atomic::AtomicU32::new(0));
    let c1 = c.clone(); let c2 = c.clone();
    std::thread::scope(|s| {
        s.spawn(move || { for _ in 0..500 { let g = acquire(&p1).expect("A"); drop(g); if acquire(&p1).is_err() { c1.fetch_add(1, std::sync::atomic::Ordering::Relaxed); } } });
        s.spawn(move || { for _ in 0..500 { let g = acquire(&p2).expect("B"); drop(g); if acquire(&p2).is_err() { c2.fetch_add(1, std::sync::atomic::Ordering::Relaxed); } } });
    });
    println!("collision-failures={}", c.load(std::sync::atomic::Ordering::Relaxed));
}
