{"command": "cd /tmp/lprobe && cat > lock_fork_repro.rs <<'EOF'
//! 假说:spawn 子进程时,fork 出来的子进程会**继承**本进程里别的线程正持有的
//! flock fd(同一个 open file description)⇒ 母进程 drop 之后锁并未真正释放。
use std::fs::OpenOptions;
use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};
use std::sync::Arc;

fn acquire(path: &std::path::Path) -> Result<std::fs::File, ()> {
    let f = OpenOptions::new().read(true).write(true).create(true).truncate(false)
        .open(path).unwrap();
    f.try_lock().map(|_| f).map_err(|_| ())
}

fn main() {
    let fails = Arc::new(AtomicU32::new(0));
    let stop = Arc::new(AtomicBool::new(false));

    let f2 = fails.clone();
    let s2 = stop.clone();
    std::thread::scope(|s| {
        // 线程 A:反复 "持有 -> drop -> 立刻重新获取"(= second_guard 的形状)
        s.spawn(move || {
            let path = std::env::temp_dir().join("forkrepro-A.lock");
            let _ = std::fs::remove_file(&path);
            let mut n = 0u32;
            while !s2.load(Ordering::Relaxed) {
                let g = acquire(&path).expect("A 第一次");
                drop(g);
                if acquire(&path).is_err() {
                    f2.fetch_add(1, Ordering::Relaxed);
                }
                n += 1;
            }
            println!("A iterations={n}");
            let _ = std::fs::remove_file(&path);
        });
        // 线程 B:反复 spawn 子进程(= another_process 的形状)
        for _ in 0..3 {
            s.spawn(|| {
                for _ in 0..120 {
                    let mut c = std::process::Command::new("/bin/sleep")
                        .arg("0.02")
                        .stdout(std::process::Stdio::null())
                        .stderr(std::process::Stdio::null())
                        .spawn().expect("spawn");
                    let _ = c.wait();
                }
            });
        }
        std::thread::sleep(std::time::Duration::from_secs(6));
        stop.store(true, Ordering::Relaxed);
        // B 线程要跑完;A 已退出
        s.spawn(|| {});
    });
    println!("reacquire failures while spawning children = {}", fails.load(Ordering::Relaxed));
}
EOF
