{"command": "cd /tmp/lprobe && cat > lock_race.rs <<'EOF'
//! 验证根因:线程 A 每轮"持有→drop→立刻重新获取";线程 B 反复 fork+exec 子进程。
//! 若 fork 的瞬间正好复制了 A 的锁 fd,子进程 exec 前那一小段时间内锁被"多持一份",
//! A 的重新获取就会失败。
use std::fs::OpenOptions;
use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};
use std::sync::Arc;

fn acquire(path: &std::path::Path) -> Result<std::fs::File, ()> {
    let f = OpenOptions::new().read(true).write(true).create(true).truncate(false)
        .open(path).unwrap();
    f.try_lock().map(|_| f).map_err(|_| ())
}

fn main() {
    let fails = Arc::new(AtomicU32::new(0));
    let rounds = Arc::new(AtomicU32::new(0));
    let done = Arc::new(AtomicBool::new(false));
    let holder = Arc::new(std::sync::Mutex::new(Vec::<std::fs::File>::new()));

    let f = fails.clone(); let r = rounds.clone(); let d = done.clone(); let h = holder.clone();
    std::thread::scope(|s| {
        s.spawn(move || {
            let path = std::env::temp_dir().join(format!("race-{}.lock", std::process::id()));
            let _ = std::fs::remove_file(&path);
            while !d.load(Ordering::Relaxed) {
                let g = match acquire(&path) { Ok(g) => g, Err(_) => { f.fetch_add(1, Ordering::Relaxed); continue; } };
                // 故意把"持有"拉长一点,让 fork 更容易撞上
                std::hint::spin_loop();
                drop(g);
                if acquire(&path).is_err() { f.fetch_add(1, Ordering::Relaxed); }
                r.fetch_add(1, Ordering::Relaxed);
            }
            let _ = h.lock();
            let _ = std::fs::remove_file(&path);
        });
        for _ in 0..4 {
            s.spawn(|| {
                while !done.load(Ordering::Relaxed) {
                    let _ = std::process::Command::new("/bin/true")
                        .stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null())
                        .spawn().map(|mut c| c.wait());
                }
            });
        }
        std::thread::sleep(std::time::Duration::from_secs(8));
        done.store(true, Ordering::Relaxed);
    });
    println!("rounds={} fails={}", rounds.load(Ordering::Relaxed), fails.load(Ordering::Relaxed));
}
EOF
rustc -O lock_race.rs -o lock_race --edition 2021 2>&1|grep -E "^error" -A4|head; for i in 1 2 3; do ./lock_race; done", "description": "Prove fork window race"}

