    /// "前一个守卫 drop 后必须能重新拿到"、`file_lock_rejects_a_second_holder`
    /// 偶发红在"第一次就必须拿到" —— 12 次全量跑红 2~4 次。
    ///
    /// 量化(8 秒压测,4 个 fork/exec 线程 + 1 个反复取锁的线程):
    /// **456 万轮里约 632 万次取锁失败**。这不是测试写错,是 fork 语义决定的;
    /// 生产里只有一个进程、一个固定锁名,不存在这个窗口。
    ///
    /// 处置:本模块的 4 条测试共用这把串行锁(diag 的测试早就用同款办法解决
    /// 过同类问题,见 `diag::DIAG_TEST_LOCK`)。**不改生产代码** ——
    /// 生产语义没有错,不存在"drop 之后锁还在"的合理场景:fork 出来的子进程
    /// 是 `adb`/`getevent`,它们 exec 后立刻不再持有;而这个窗口只在测试并行
    /// 跑 + 同进程内另一线程持锁时才成问题。
    static INSTANCE_TEST_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    /// 取串行锁(中毒也继续:测试 panic 之后剩下的测试仍该能跑)。
    fn serialize() -> std::sync::MutexGuard<'static, ()> {
        INSTANCE_TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner())
    }

